<?php use App\Core\Csrf; use App\Core\View; $labels=['single'=>'单选题','multiple'=>'多选题','judge'=>'判断题','fill'=>'填空题']; ?>
<div class="page-head"><div><h1>本次练习完成</h1><p><?= View::e($attempt['set_title']) ?> · <?= $attempt['question_mode']==='random'?'随机出题':'顺序抽取' ?></p></div><a class="btn" href="/student">返回学习中心</a></div>
<section class="card"><div class="grid grid-3"><div class="stat"><strong><?= (int)$attempt['correct_count'] ?>/<?= (int)$attempt['total_count'] ?></strong><span>答对题数</span></div><div class="stat"><strong><?= View::e($attempt['score_percent']) ?>%</strong><span>正确率</span></div><div class="stat"><strong><?= View::e($attempt['submitted_at']) ?></strong><span>完成时间</span></div></div><form class="top-gap" method="post" action="/student/practice/<?= $attempt['practice_set_id'] ?>/start"><?= Csrf::field() ?><input type="hidden" name="question_mode" value="<?= View::e($attempt['question_mode']) ?>"><button class="btn btn-primary">再练一次</button></form></section>
<?php foreach($questions as$q):$options=json_decode($q['options_json'],true)?:[];$selected=json_decode($q['selected_answers_json']??'[]',true)?:[];$correct=json_decode($q['correct_answers_json'],true)?:[];?><article class="card"><div class="question-number">第 <?= $q['display_order'] ?> 题 · <?= View::e($labels[$q['question_type']]??$q['question_type']) ?> · <span class="<?= $q['is_correct']?'':'danger-text' ?>"><?= $q['is_correct']?'回答正确':'回答错误' ?></span></div><h3><?= View::e($q['title']) ?></h3><div class="prompt"><?= nl2br(View::e($q['prompt'])) ?></div><?php if($q['question_type']==='fill'):?><p>你的答案：<strong><?= View::e($selected[0]??'未作答') ?></strong></p><?php else:?><div class="options"><?php foreach($options as$letter=>$text):?><div class="option <?= in_array($letter,$correct,true)?'answer-reference':'' ?>"><strong><?= $q['question_type']==='judge'?View::e($text):View::e($letter).'.' ?></strong><?php if($q['question_type']!=='judge'):?><span><?= View::e($text) ?></span><?php endif;?><?php if(in_array($letter,$selected,true)):?><span class="badge">你的选择</span><?php endif;?></div><?php endforeach;?></div><?php endif;?><h4>正确答案：<?php if($q['question_type']==='judge')echo (($correct[0]??'')==='T'?'对':'错');else echo View::e($correct?implode(' / ',$correct):'题库原文未提供标准答案');?></h4><?php if($q['explanation']):?><div class="answer-reference"><?= nl2br(View::e($q['explanation'])) ?></div><?php else:?><div class="muted">题库未提供详细解析。</div><?php endif;?></article><?php endforeach;?>
